const img = code.match(/<img[^>]*>/i);
if (!img) {
  throw new Error("The image element went missing — it should stay.");
}
if (!/alt\s*=\s*["'][^"']+["']/i.test(img[0])) {
  throw new Error("The <img> has no alt attribute — every meaningful image needs one.");
}
const alt = (img[0].match(/alt\s*=\s*["']([^"']*)["']/i) || [])[1] ?? "";
const worthless = ["image", "photo", "picture", "img", "jpg", "png"];
if (alt.trim().length < 4 || worthless.includes(alt.trim().toLowerCase())) {
  throw new Error("The alt text should describe what the image shows (e.g. 'A bowl of handmade pasta').");
}

const link = code.match(/<a\s[^>]*href\s*=\s*["']https:\/\/example\.com\/menu["'][^>]*>([\s\S]*?)<\/a>/i);
if (!link) {
  throw new Error("Keep the link to https://example.com/menu.");
}
const text = link[1].replace(/<[^>]+>/g, "").trim().toLowerCase();
if (!text || /click here|here|this link|more/.test(text)) {
  throw new Error("'click here' tells screen-reader users nothing — describe the destination (e.g. 'View the full menu').");
}

const headings = [...code.matchAll(/<h([1-6])[\s>]/gi)].map((m) => Number(m[1]));
if (headings.some((l) => l === 4 || l === 5 || l === 6)) {
  throw new Error("Still skipping heading levels — the section after <h1> should be <h2>, not <h4>.");
}
if (!(headings.includes(1) && headings.includes(2))) {
  throw new Error("Use <h1> for the page title and <h2> for the next section heading.");
}

if (!/<ul[\s>][\s\S]*?<\/ul>/i.test(code)) {
  throw new Error("No <ul> found — the unordered ingredient list is missing.");
}
const ulBlock = code.match(/<ul[\s>][\s\S]*?<\/ul>/i)[0];
const ulItems = (ulBlock.match(/<li[\s>]/gi) || []).length;
if (ulItems < 3) {
  throw new Error("The <ul> should hold the three ingredients as <li> items.");
}
if (/tomatoes[\s\S]*basil[\s\S]*olive oil/i.test(code.match(/<ol[\s>][\s\S]*?<\/ol>/i)?.[0] ?? "")) {
  throw new Error("The three ingredients are still inside the <ol> — move them into the <ul>.");
}

const sections = code.match(/<section[\s>][\s\S]*?<\/section>/gi) || [];
const target = sections.find((s) => /opening hours/i.test(s));
if (!target) {
  throw new Error("Add a <section> containing an <h2> that says 'Opening hours'.");
}
if (!/<h2[^>]*>\s*opening hours\s*<\/h2>/i.test(target)) {
  throw new Error("The section's heading must be <h2>Opening hours</h2>.");
}
const ul = target.match(/<ul[\s>][\s\S]*?<\/ul>/i);
if (!ul || (ul[0].match(/<li[\s>]/gi) || []).length < 2) {
  throw new Error("Inside the section, add a <ul> with at least two <li> entries.");
}

const btn = code.match(/<button[^>]*type\s*=\s*["']button["'][^>]*>[\s\S]*?<\/button>/i);
if (!btn) {
  throw new Error("Add <button type=\"button\">Book a table</button>.");
}
if (!/book a table/i.test(btn[0])) {
  throw new Error("The button's visible text must be 'Book a table'.");
}
